from fastapi import APIRouter, Depends, HTTPException

async def get_workspace_context(
    workspace_id: str,
    role_service: RoleService = Depends(get_role_service),
    current_user: User = Depends(get_authenticated_user)
) -> WorkspaceSecurityContext:
    user_role = await role_service.get_user_workspace_role(current_user.id, workspace_id)
    if not user_role or user_role.role != "admin":
        raise HTTPException(status_code=403, detail="Forbidden: user lacks admin permissions in this workspace")

    return WorkspaceSecurityContext(workspace_id=workspace_id, role=user_role.role)

router = APIRouter(prefix="/cloud/workspaces")

@router.get("/{workspace_id}/api-secrets")
async def get_workspace_secrets(
    workspace_id: str,
    sec_ctx: WorkspaceSecurityContext = Depends(get_workspace_context, use_cache=False),
    secret_vault: SecretVault = Depends(get_secret_vault)
):
    secrets = await secret_vault.retrieve_workspace_secrets(sec_ctx.workspace_id)
    return {"workspace_id": workspace_id, "secrets": secrets}
